    const auto loaded = t.run(memory, Json{{"action","load"},{"name","style"}});
    CHECK_MSG(((loaded.content.find("Conventional Commits") != std::string::npos)) == (true), "include/mini_agent/tools/builtin.hpp:255 的示例失效了");
